/** A message as returned by every send and message endpoint. */
export interface Message {
  /** Your `clientMessageId` (generated by the SDK when you do not pass one). */
  id: string;
  /** WhatsApp message id, once sent. */
  externalId: string | null;
  to: string;
  type: string;
  status: 'queued' | 'scheduled' | 'sent' | 'delivered' | 'read' | 'failed' | 'canceled' | string;
  error: string | null;
  scheduledAt: string | null;
  sentAt: string | null;
  deliveredAt: string | null;
  readAt: string | null;
  editedAt: string | null;
  revokedAt: string | null;
  createdAt: string;
  /** True when the same clientMessageId was already accepted (nothing was sent again). */
  duplicate?: boolean;
  /** Set by delete: `canceled` (still queued) or `revoked` (deleted for everyone). */
  action?: 'canceled' | 'revoked';
}

/** Body of every webhook delivery. */
export interface WebhookEvent<T = Record<string, unknown>> {
  event: string;
  instanceId?: string;
  /** Unix time in milliseconds. */
  timestamp?: number;
  sandbox?: boolean;
  data: T;
  [key: string]: unknown;
}
